//! Native INPUT maxLength and actual UTF-16 insertion admission.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><input id=area name=q value=Seed><input id=prefix maxlength=' +2tail'><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://input-max-length.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn input_max_length_canonical_descriptor_and_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'maxLength');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get maxLength'||a.set.name!=='set maxLength'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'maxLength')||x.maxLength!==-1)throw 'canonical maxLength';var calls=0;x.maxLength={valueOf:function(){calls++;return 2;}};if(calls!==1||x.maxLength!==2||x.getAttribute('maxlength')!=='2'||x.value!=='Seed'||x.defaultValue!=='Seed')throw 'actual reflected limit';");}
#[test]
fn input_max_length_author_limit_crosses_former_4096_clamp(){let d=crate::html::parse("<form><input id=large name=q maxlength=5000></form>");let mut f=Forms::new(&d);let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("large")).unwrap();assert_eq!(f.controls[&n].max_length,5000,"authored maxlength is not a browser capacity ceiling");f.controls.get_mut(&n).unwrap().insert(&"X".repeat(5001));assert_eq!(f.controls[&n].value.text(),"X".repeat(5000));}
#[test]
fn input_max_length_public_attribute_update_native_limit_and_remove(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.setAttribute('maxlength','2');if(x.maxLength!==2||x.value!=='Seed')throw 'content limit reflection';");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();assert_eq!(f.controls[&n].max_length,2);run(&mut d,&mut f,&mut p,"x.removeAttribute('maxlength');if(x.maxLength!==-1)throw 'removed limit';");assert_eq!(f.controls[&n].max_length,usize::MAX);}
#[test]
fn input_max_length_initial_html_prefix_admits_actual_native_units(){let(d,mut f,_)=fixture();let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("prefix")).unwrap();assert_eq!(f.controls[&n].max_length,2);f.controls.get_mut(&n).unwrap().insert("😀Z");assert_eq!(f.controls[&n].value.text(),"😀");}
#[test]
fn input_max_length_negative_converted_long_is_real_dom_exception(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'maxLength'),calls=0;for(var bad of [-1,2147483648,4294967295]){try{a.set.call(x,{valueOf:function(){calls++;return bad;}});throw 'missing negative refusal';}catch(e){if(!(e instanceof DOMException)||e.name!=='IndexSizeError')throw e;}}if(calls!==3||x.getAttribute('maxlength')!==null||x.value!=='Seed')throw 'atomic negative limit';x.maxLength=4294967296;if(x.maxLength!==0||x.getAttribute('maxlength')!=='0')throw 'ToInt32 wrapping';");}

#[test]
fn input_max_length_getter_prefix_matrix_native_inert_and_exact_raw_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','input');for(var target of [x,inert]){for(var pair of [['',-1],['-1',-1],['0',0],['-0',0],[' +2tail',2],['3.8',3],['0x20',0],['2147483647',2147483647],['2147483648',-1],['\u00a04',-1],['+4\ud800tail',4]]){target.setAttribute('maxlength',pair[0]);if(target.maxLength!==pair[1]||target.getAttributeNS(null,'maxlength')!==pair[0])throw 'HTML nonnegative prefix or exact record';}target.removeAttribute('maxlength');if(target.maxLength!==-1)throw 'missing limit';target.setAttributeNS('urn:other','maxlength','1');target.setAttributeNS(null,'MAXLENGTH','1');if(target.maxLength!==-1)throw 'namespace alias drove limit';target.setAttributeNS(null,'maxlength','2');if(target.maxLength!==2||target.getAttributeNS('urn:other','maxlength')!=='1'||target.getAttributeNS(null,'MAXLENGTH')!=='1')throw 'canonical null namespace';}if(x.value!=='Seed'||x.defaultValue!=='Seed')throw 'read altered value';"#);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();assert_eq!(f.controls[&n].max_length,2);}
#[test]
fn input_max_length_setter_long_conversion_once_reentrant_abrupt_and_type_errors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area');for(var pair of [[undefined,0],[null,0],[NaN,0],[Infinity,0],[-Infinity,0],[-0,0],[-0.9,0],[1.9,1],[4294967299,3],[-4294967292,4]]){x.maxLength=pair[0];if(x.maxLength!==pair[1]||x.getAttributeNS(null,'maxlength')!==String(pair[1]))throw 'signed long conversion';}var calls=0;x.maxLength={valueOf:function(){calls++;x.maxLength=2;return 5;}};if(calls!==1||x.maxLength!==5)throw 'current outer conversion';var marker={};try{x.maxLength={valueOf:function(){calls++;x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(calls!==2||x.maxLength!==5||x.getAttribute('data-side')!=='kept')throw 'abrupt conversion state';for(var bad of [Symbol('bad'),BigInt(1)]){try{x.maxLength=bad;throw 'missing numeric type error';}catch(e){if(!(e instanceof TypeError))throw e;}}if(x.maxLength!==5||x.value!=='Seed')throw 'type error mutation';"#);}
#[test]
fn input_max_length_all_attribute_producers_sync_native_without_rebuilding_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='dirty';x.maxLength=5;var attribute=x.getAttributeNodeNS(null,'maxlength'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['maxlength']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('maxlength',' +2tail');","x.setAttributeNS(null,'maxlength',' +2tail');","attribute.value=' +2tail';","attribute.nodeValue=' +2tail';","attribute.textContent=' +2tail';"]{p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.maxLength!==2||x.getAttributeNodeNS(null,'maxlength')!==attribute||records.length!==1||records[0].target!==x||records[0].attributeName!=='maxlength'||x.value!=='dirty'||x.defaultValue!=='Seed')throw 'actual attribute update';");let c=&f.controls[&n];assert_eq!((c.max_length,c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(2,3,1,2,true));}run(&mut d,&mut f,&mut p,"var replacement=document.createAttribute('maxlength');replacement.value='1';");let before=format!("{:?}",d.nodes);let error=p.runtime.execute("x.attributes.setNamedItemNS(replacement);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("NamedNodeMap mutation"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls[&n].max_length,2);p.begin_job();run(&mut d,&mut f,&mut p,"if(x.maxLength!==2||x.getAttributeNodeNS(null,'maxlength')!==attribute||replacement.ownerElement!==null)throw 'unsupported map mutation atomicity';x.setAttributeNodeNS(replacement);if(x.maxLength!==1||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'attached replacement';");assert_eq!(f.controls[&n].max_length,1);}
#[test]
fn input_max_length_changes_future_utf16_insertions_only_and_accepts_full_signed_bound(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.maxLength=1;x.value='long 😀 value';if(x.value!=='long 😀 value')throw 'script value truncated';x.defaultValue='new long default';if(x.value!=='long 😀 value')throw 'dirty default changed live';x.value='';");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();f.controls.get_mut(&n).unwrap().insert("😀Z");assert_eq!(f.controls[&n].value.text(),"");run(&mut d,&mut f,&mut p,"x.maxLength=3;");f.controls.get_mut(&n).unwrap().insert("😀ZQ");assert_eq!(f.controls[&n].value.text(),"😀Z");run(&mut d,&mut f,&mut p,"x.maxLength=0;if(x.value!=='😀Z')throw 'lower limit truncated existing';");f.controls.get_mut(&n).unwrap().insert("Q");assert_eq!(f.controls[&n].value.text(),"😀Z");run(&mut d,&mut f,&mut p,"x.maxLength=2147483647;");assert_eq!(f.controls[&n].max_length,2147483647);}
#[test]
fn input_max_length_fragment_copy_detach_reconnect_native_limits_stay_independent(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.createElement('div');host.innerHTML='<input id=fresh maxlength=" +2tail">';var x=host.firstChild;document.body.appendChild(host);if(x.maxLength!==2)throw 'fragment prefix';x.value='dirty';var copy=x.cloneNode(true);copy.maxLength=1;if(copy.maxLength!==1||copy.value!=='dirty'||x.maxLength!==2)throw 'dirty copied limit';x.parentNode.removeChild(x);x.maxLength=3;document.getElementById('form').appendChild(x);if(x.maxLength!==3||x.value!=='dirty'||x.form!==document.getElementById('form'))throw 'reconnected limit';"#);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("fresh")&&f.controls[n].owner.is_some()).unwrap();assert_eq!(f.controls[&n].max_length,3);let copied=f.controls.iter().find(|(node,_)|**node!=n&&d.attr(**node,"id")==Some("fresh")).unwrap().1;assert_eq!(copied.max_length,1);}
#[test]
fn input_max_length_brands_saved_accessors_and_author_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),P=HTMLInputElement.prototype,a=Object.getOwnPropertyDescriptor(P,'maxLength'),calls=0;for(var bad of [{},document,document.createElement('textarea'),Object.create(P)]){try{a.set.call(bad,{valueOf:function(){calls++;return 2;}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls||x.maxLength!==-1)throw 'bad brand converted';Object.defineProperty(P,'maxLength',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.maxLength='override';a.set.call(x,3);if(x.maxLength!=='author'||a.get.call(x)!==3||x.getAttribute('data-author')!=='override')throw 'saved authority';delete P.maxLength;if(x.maxLength!==undefined)throw 'deleted hidden member';Object.defineProperty(P,'maxLength',a);var C=HTMLInputElement;delete window.HTMLInputElement;if(!(x instanceof C)||a.get.call(x)!==3)throw 'saved roots';");}
#[test]
fn input_max_length_resource_refusal_preserves_attributes_native_limit_editor_and_recovers(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='dirty';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("input")};let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();let nodes=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);let capture=|f:&Forms|{let c=&f.controls[&n];(c.max_length,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)};let before=capture(&f);let retained=p.state.retained_limit;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.input_max_length_set(object,&Value::Number(2.0)).is_err());assert_eq!(format!("{:?}",d.nodes),nodes);assert_eq!((p.state.retained,p.state.dom_commits),state);assert_eq!(capture(&f),before);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.maxLength=2;if(x.maxLength!==2||x.value!=='dirty')throw 'fresh limit recovery';");}}
#[test]
fn input_max_length_reads_are_allocation_free_and_saved_child_origin_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.maxLength=3;var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'maxLength'),calls=0;if(a.get.call(x)!==3)throw 'same origin getter';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("input")};let retained=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.state.limits.host.string_bytes=0;assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.input_max_length_get(object),Ok(Value::Number(3.0))));p.state.retained_limit=retained;p.state.limits.host.string_bytes=strings;p.set_location(&crate::navigation::address("https://foreign-input-max-length.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("a.set.call(x,{valueOf:function(){calls++;return 1;}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://input-max-length.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.maxLength!==3)throw 'origin converted';a.set.call(x,2);if(a.get.call(x)!==2)throw 'fresh origin recovery';");}
#[test]
fn input_length_text_clone_dirty_defaults_selection_and_independent_flags(){for deep in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area');x.value='dirty😀';x.defaultValue='A\r\nB';x.required=true;x.readOnly=true;x.maxLength=5000;x.minLength=2;"#);let n=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}run(&mut d,&mut f,&mut p,&format!("var copy=x.cloneNode({deep});if(copy===x||copy.parentNode!==null||copy.form!==null||copy.value!=='dirty😀'||copy.defaultValue!=='A\\r\\nB'||!copy.required||!copy.readOnly||copy.maxLength!==5000||copy.minLength!==2)throw 'copied dirty flags';copy.defaultValue='Other';copy.maxLength=1;copy.minLength=0;copy.required=false;copy.readOnly=false;if(copy.value!=='dirty😀'||x.defaultValue!=='A\\r\\nB'||x.maxLength!==5000||x.minLength!==2||!x.required||!x.readOnly)throw 'independent default and flags';copy.value='new';document.getElementById('form').appendChild(copy);if(copy.form!==document.getElementById('form')||copy.value!=='new'||x.value!=='dirty😀')throw 'clone reconnect';"));let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}}
#[test]
fn input_length_text_clone_resource_refusal_preserves_native_state_and_recovers(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='dirty';x.maxLength=5000;");let before=(format!("{:?}",d.nodes),f.controls.iter().map(|(&n,c)|(n,(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset),(c.name.clone(),c.caption.clone(),c.owner,c.group_root),(c.disabled,c.readonly,c.required,c.checked,c.dirty_checked,c.dirty_value),c.max_length,c.tab_index)).collect::<Vec<_>>());let retained=p.state.retained_limit;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let err=p.runtime.execute("x.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(!err.is_empty());assert_eq!((format!("{:?}",d.nodes),f.controls.iter().map(|(&n,c)|(n,(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset),(c.name.clone(),c.caption.clone(),c.owner,c.group_root),(c.disabled,c.readonly,c.required,c.checked,c.dirty_checked,c.dirty_value),c.max_length,c.tab_index)).collect::<Vec<_>>()),before);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"var copy=x.cloneNode(false);if(copy.value!=='dirty'||copy.maxLength!==5000||x.value!=='dirty')throw 'clone resource recovery';");}}
#[test]
fn input_length_text_clone_mixed_native_editor_and_radio_plan_stays_independent(){let mut d=crate::html::parse("<div id=group><input id=txt name=q value=Seed maxlength=5000><textarea id=area>Old</textarea><input id=radio type=radio name=r checked></div>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var g=document.getElementById('group'),x=document.getElementById('txt'),a=document.getElementById('area'),r=document.getElementById('radio');x.value='Edited';a.value='Area';var copy=g.cloneNode(true),cx=copy.firstChild,ca=cx.nextSibling,cr=ca.nextSibling;if(cx.value!=='Edited'||cx.defaultValue!=='Seed'||cx.maxLength!==5000||ca.value!=='Area'||!cr.checked||!r.checked)throw 'mixed copied native state';cx.value='Copy';ca.value='Copy area';cr.checked=false;if(x.value!=='Edited'||a.value!=='Area'||!r.checked)throw 'mixed source isolated';");assert_eq!(f.controls.len(),6);}
